def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    danger_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                danger_opp += 1
            if opp.get('budget', 0) >= 700:
                rich_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    slots = max(1, int(supply // WATER_REQ))
    total_players = 1 + len(alive_opponents)
    scarcity = total_players - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 6:
        urgency += 2
    else:
        urgency += 1

    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2

    if slots <= 1:
        urgency += 3
    elif slots == 2:
        urgency += 2
    else:
        urgency += 1

    if scarcity >= 3:
        urgency += 2
    elif scarcity >= 1:
        urgency += 1

    if danger_opp >= 2:
        urgency += 1

    if budget < DAILY_SALARY * 2:
        urgency += 1

    if urgency <= 3:
        base = DAILY_SALARY * 0.28
    elif urgency <= 5:
        base = DAILY_SALARY * 0.48
    elif urgency <= 7:
        base = DAILY_SALARY * 0.72
    elif urgency <= 9:
        base = DAILY_SALARY * 0.96
    else:
        base = DAILY_SALARY * 1.22

    if highest_prev > 0:
        if urgency <= 4 and highest_prev >= DAILY_SALARY * 1.4:
            bid = DAILY_SALARY * 0.32
        elif urgency >= 8:
            bid = max(base, min(highest_prev + 2.0, DAILY_SALARY * 1.55))
        else:
            target = avg_prev * 0.92 + 3.0
            bid = max(base, min(target, highest_prev + 1.0))
    else:
        bid = base

    if rich_opp >= 2 and slots <= 1 and urgency <= 6:
        bid = min(bid, DAILY_SALARY * 0.55)

    remaining_days = max(0, 10 - int(day))
    reserve = 0.0
    if remaining_days > 0:
        reserve = remaining_days * DAILY_SALARY * 0.22
    affordable = max(0.0, budget - reserve)

    if urgency >= 8:
        final_bid = min(budget, max(bid, DAILY_SALARY * 0.9))
    else:
        final_bid = min(bid, max(DAILY_SALARY * 0.18, affordable))
        final_bid = min(final_bid, budget)

    if hp <= 2 or no_water_days >= 2:
        final_bid = min(budget, max(final_bid, highest_prev + 2.5 if highest_prev > 0 else DAILY_SALARY * 0.95))

    if final_bid < 0:
        final_bid = 0.0

    return float(round(final_bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 40.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0
    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 1.2)
    if day_context['supply'] < WATER_REQ * 1.5:
        return min(my_status['budget'], avg_prev_bid * 1.05)
    return min(my_status['budget'], max(40.0, avg_prev_bid * 0.9))
